const fields = $json.body.data.fields;

const getField = (label) => {
  const f = fields.find(f => (f.label || '').trim().toLowerCase() === label.toLowerCase());
  return f ? f.value : null;
};

return [{
  json: {
    namn: getField('Namn'),
    epost: getField('E-post'),
    telefon: getField('Telefon'),
    meddelande: getField('Meddelande'),
    objekt: getField('objekt')
  }
}];

const lead = $('Extract lead fields').item.json;

let category;
try {
  category = JSON.parse($json.output[0].content[0].text);
} catch (e) {
  category = { temperatur: 'kallt', prioritet: 'låg', motivering: 'Kunde inte tolka AI-svaret.' };
}

return [{
  json: {
    namn: lead.namn,
    'e-post': lead.epost,
    telefon: lead.telefon,
    objekt: lead.objekt,
    meddelande: lead.meddelande,
    temperatur: category.temperatur,
    prioritet: category.prioritet,
    motivering: category.motivering
  }
}];

const raw = $('Format output').item.json;
const rows = $input.all();

// Städa objektnamnet för visning i mejlen
const lead = { ...raw, objekt: (raw.objekt ?? '').toString().trim() };

// Normalisera: ignorera mellanslag och skillnad på stora/små bokstäver vid matchning
const normalize = (v) => (v ?? '').toString().trim().toLowerCase();

// Gör även KOLUMNNAMN toleranta
const fieldGetter = (obj) => {
  const map = {};
  for (const key of Object.keys(obj)) {
    map[normalize(key)] = obj[key];
  }
  return (name) => map[normalize(name)];
};

const target = normalize(lead.objekt);

const match = target === ''
  ? null
  : rows.find(r => r.json && normalize(fieldGetter(r.json)('Objekt')) === target);

if (match) {
  const get = fieldGetter(match.json);
  return [{
    json: {
      ...lead,
      brokerFound: true,
      maklare: (get('Mäklare') ?? '').toString().trim(),
      maklarEmail: (get('Mäklarmejl') ?? '').toString().trim(),
      byra: (get('Byrå') ?? '').toString().trim(),
      annonslank: (get('Annonslänk') ?? '').toString().trim()
    }
  }];
}

return [{
  json: {
    ...lead,
    brokerFound: false,
    maklare: null,
    maklarEmail: null,
    byra: null,
    annonslank: null
  }
}];

