const lead = $json;

const pad = (n) => String(n).padStart(2, '0');
const d = new Date();
const datum = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;

// Nyckelordningen här blir kolumnordningen i Leads-fliken.
// Vid fallback (objekt hittades inte) blir Mäklare och Annonslänk tomma.
return [{
  json: {
    'Datum': datum,
    'Namn': lead.namn ?? '',
    'E-post': lead['e-post'] ?? '',
    'Telefon': lead.telefon ?? '',
    'Objekt': lead.objekt ?? '',
    'Meddelande': lead.meddelande ?? '',
    'Temperatur': lead.temperatur ?? '',
    'Prioritet': lead.prioritet ?? '',
    'Motivering': lead.motivering ?? '',
    'Mäklare': lead.maklare ?? '',
    'Annonslänk': lead.annonslank ?? ''
  }
}];

const rows = $input.all();

const normalize = (v) => (v ?? '').toString().trim().toLowerCase();

// Toleranta kolumnnamn (mellanslag/versaler spelar ingen roll)
const fieldGetter = (obj) => {
  const map = {};
  for (const key of Object.keys(obj)) {
    map[normalize(key)] = obj[key];
  }
  return (name) => map[normalize(name)];
};

const out = [];

for (const row of rows) {
  if (!row.json) continue;
  const get = fieldGetter(row.json);

  // VIKTIGT: skriv tillbaka objektet EXAKT som det står i arket,
  // annars hittar appendOrUpdate ingen matchande rad och skapar en dubblett.
  const objektRaw = (get('Objekt') ?? '').toString();
  const objektRen = objektRaw.trim();
  const befintligLank = (get('Formulärlänk') ?? '').toString().trim();

  // Hoppa över tomma rader och rader som redan har länk
  if (objektRen === '' || befintligLank !== '') continue;

  const encoded = encodeURIComponent(objektRen).replace(/%20/g, '+');

  out.push({
    json: {
      Objekt: objektRaw,
      'Formulärlänk': `https://tally.so/r/kdjp16?objekt=${encoded}`
    }
  });
}

return out;
